# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊 hyper','在上；越过；过量'],['英语 hyper-','超过通常范围；超出']]
W=[
E('hyper','英 /ˈhaɪpə/；美 /ˈhaɪpər/','亢奋的；特别兴奋活跃的〔口语〕','像把精力旋钮拧得过高，坐不住、话多、情绪很兴奋。','常见形容词用法缩自 hyperactive；更早的构词材料是希腊 hyper，表示超过、过量。',B+[['hyperactive → hyper','过度活跃的 → 口语缩写“特别亢奋”']],'The kids are hyper today 是说孩子们今天特别兴奋、闹腾。口语里的 hyper 常是当时状态的轻松描述，不是正式诊断某种疾病。','feel hyper；get hyper；be really hyper。','hyper 比 happy 多了精力过盛、过分兴奋的感觉。一个人说自己 hyper，并不自动等于患有 ADHD。',('I felt strangely hyper after the exciting news.','听到这个令人兴奋的消息后，我整个人兴奋得有点停不下来。'),('The children were too hyper to sit through the long speech.','孩子们太兴奋了，没法安静坐着听完那场长讲话。'),sources=['https://www.etymonline.com/word/hyper','https://en.wiktionary.org/wiki/hyper']),
E('hyperactive','/ˌhaɪpərˈæktɪv/','过度活跃的；活动过多的','不只是动得起来，而是活动量高到难以停下来或超过情境所需。','hyper- 过度 + active 活跃的；是英语利用前缀组成的词。',B+[['hyper- + active → hyperactive','活跃程度过高的']],'a hyperactive child 描述活动过多的孩子；a hyperactive imagination 可比喻想象特别活跃、停不下来。临床语境和日常夸张用法需要分开，不靠一个形容词判断具体诊断。','hyperactive behavior；a hyperactive imagination；an unusually hyperactive period。','active 往往中性或正面，hyperactive 多了超过通常程度这一层。hyperactivity 是相应名词。',('The novel follows a child with a hyperactive imagination.','小说讲述了一个想象力异常活跃的孩子。'),('The report describes hyperactive behavior in several different settings.','报告描述了在几种不同环境中出现的过度活跃行为。'),sources=['https://www.etymonline.com/word/hyperactive','https://en.wiktionary.org/wiki/hyperactive']),
E('hypersensitivity','英 /ˌhaɪpəsensəˈtɪvəti/；美 /ˌhaɪpərsensəˈtɪvəti/','过度敏感；超敏反应','像感应器的灵敏度开得太大，一点刺激就引起明显反应。','hyper- 过度 + sensitivity 敏感性；现代也可与 hypersensitive + -ity 对应理解。',B+[['hyper- + sensitivity → hypersensitivity','超出通常程度的敏感或反应']],'hypersensitivity to criticism 是对批评过度敏感；医学中的 drug hypersensitivity 指对药物的超敏反应。这两种场景共享“反应过强”的直觉，但心理感受与免疫机制不是同一回事。','hypersensitivity to something；drug hypersensitivity；a hypersensitivity reaction。','sensitivity 是敏感性，hypersensitivity 强调过度或异常。不能把免疫学的超敏反应简单说成人太玻璃心。',('His hypersensitivity to criticism made teamwork difficult.','他对批评过度敏感，让团队合作变得困难。'),('The paper reviews drug hypersensitivity reactions.','论文综述了药物超敏反应。'),sources=['https://www.merriam-webster.com/dictionary/hypersensitivity','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hypersensitivity','https://en.wiktionary.org/wiki/hypersensitivity']),
E('hyperinflation','英 /ˌhaɪpərɪnˈfleɪʃən/；美 /ˌhaɪpərɪnˈfleɪʃən/','恶性通货膨胀；极端快速的物价上涨','不是商品偶尔贵一点，而是价格涨得很快，手里的钱迅速失去购买力。','hyper- 过度 + inflation 通货膨胀；inflation 的历史有吹胀的意象，这里用在货币与价格现象上。',B+[['hyper- + inflation → hyperinflation','通胀达到极端程度']],'during hyperinflation 描述恶性通胀时期；hyperinflation eroded savings 是说积蓄的购买力被迅速侵蚀。这个词比日常“物价涨了”强得多，不应给任何小幅涨价都贴上这个标签。','a period of hyperinflation；hyperinflation eroded savings；rapid price increases。','inflation 是一般通胀，hyperinflation 是其极端状态；它也不同于 deflation 通货紧缩。',('The history book describes how hyperinflation disrupted daily life.','历史书描述了恶性通胀如何打乱日常生活。'),('During hyperinflation, prices changed so quickly that printed menus became outdated.','恶性通胀期间，价格变化太快，印好的菜单很快就过时了。'),sources=['https://en.wiktionary.org/wiki/hyperinflation','https://www.merriam-webster.com/dictionary/hyperinflation']),
E('hypersonic','英 /ˌhaɪpəˈsɒnɪk/；美 /ˌhaɪpərˈsɑnɪk/','高超声速的','先越过音速，再进入远高于音速的飞行范围。','hyper- 超过 + sonic 声音、声速相关的；在空气动力学里形成特定速度范围的术语。',B+[['hyper- + sonic → hypersonic','远高于声速的']],'hypersonic flight 通常指约五倍当地音速及以上的飞行范围；hypersonic research 研究相应气动、加热等问题。这里 sonic 指声速参照，不是声音特别响。','hypersonic flight；hypersonic speeds；hypersonic research。','supersonic 是超声速，范围比 hypersonic 广；ultrasonic 是超声波，主要说频率超出人耳范围，不是飞行速度。',('The team studies airflow at hypersonic speeds.','团队研究高超声速条件下的气流。'),('The exhibit explains why heating is important in hypersonic flight.','展览解释了为什么高超声速飞行中加热效应很重要。'),sources=['https://www.nasa.gov/hypersonics/','https://www.grc.nasa.gov/www/k-12/BGP/mach.html','https://en.wiktionary.org/wiki/hypersonic']),
E('hyperlink','英 /ˈhaɪpəlɪŋk/；美 /ˈhaɪpərlɪŋk/','超链接；给……加超链接','文本里开了一扇小门，点一下，就能跳到另一处内容。','常分析为 hyper- + link，也可看作 hypertext + link 的缩合；沿超文本概念发展，不是“过度连接”。',B+[['hypertext 与 link 的构词联系','超出线性文本的关联'],['英语 hyperlink','可跳往另一内容位置的链接']],'click a hyperlink 是点击超链接；insert a hyperlink 是插入超链接。链接可指向另一个页面，也可指向同页某处；可点击的载体不必只是文字，也可能是图片。','insert a hyperlink；click a hyperlink；a broken hyperlink；hyperlink text。','hyperlink 是连接及跳转关系；URL 是资源地址。显示的链接文字可能只是几个字，与实际目标地址不同。',('The document contains a hyperlink to the full report.','文档中有一个指向完整报告的超链接。'),('Click the hyperlink to jump to the references section.','点击超链接即可跳到参考资料部分。'),sources=['https://developer.mozilla.org/en-US/docs/Glossary/Hyperlink','https://en.wiktionary.org/wiki/hyperlink']),
E('hyperdrive','英 /ˈhaɪpədraɪv/；美 /ˈhaɪpərdraɪv/','超空间驱动装置〔科幻〕；极高速运转状态〔比喻〕','科幻飞船启动一种超越普通航行方式的驱动；日常则借它形容一下子进入全速状态。','hyper- 超越 + drive 驱动；科幻含义与 hyperspace 超空间的想象相连。',B+[['hyper- + drive → hyperdrive','超越普通航行的虚构驱动装置'],['比喻用法','活动或思维进入极快状态']],'the ship’s hyperdrive 是飞船的虚构超空间驱动；go into hyperdrive 可以说工作、宣传或思绪突然加速。它不是现实航空工程中任意高速发动机的通称。','engage the hyperdrive；the hyperdrive fails；go into hyperdrive。','hypersonic 是现实速度术语，hyperdrive 通常是科幻设定或比喻。不能因为同有 hyper- 就把两者当成同一种技术。',('In the story, the crew repairs the damaged hyperdrive.','故事里，船员修好了受损的超空间驱动装置。'),('Preparations went into hyperdrive as the opening day approached.','随着开幕日临近，各项准备工作进入了全速推进状态。'),sources=['https://en.wiktionary.org/wiki/hyperdrive','https://www.merriam-webster.com/dictionary/hyperdrive'])
]
